import React from "react";
import { Navigate, Route, Routes } from "react-router-dom";

import AdminDashboard from "./pages/AdminDashboard";
import ClientDashboard from "./pages/ClientDashboard";
import Login from "./pages/Login";
import Register from "./pages/Register";

const decodeToken = (token) => {
  const base64Value = token.split(".")[1];
  const normalized = base64Value.replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized.padEnd(normalized.length + ((4 - (normalized.length % 4)) % 4), "=");

  return JSON.parse(atob(padded));
};

const readTokenPayload = () => {
  const token = localStorage.getItem("token");
  if (!token) {
    return null;
  }

  try {
    const payload = decodeToken(token);
    return { token, payload };
  } catch (error) {
    localStorage.removeItem("token");
    return null;
  }
};

const ProtectedRoute = ({ allowedRole, children }) => {
  const auth = readTokenPayload();

  if (!auth) {
    return <Navigate to="/login" replace />;
  }

  if (auth.payload.role !== allowedRole) {
    return <Navigate to={auth.payload.role === "admin" ? "/admin" : "/"} replace />;
  }

  return children;
};

const DefaultRoute = () => {
  const auth = readTokenPayload();

  if (!auth) {
    return <Navigate to="/login" replace />;
  }

  return <Navigate to={auth.payload.role === "admin" ? "/admin" : "/"} replace />;
};

function App() {
  return (
    <Routes>
      <Route
        path="/"
        element={
          <ProtectedRoute allowedRole="client">
            <ClientDashboard view="overview" />
          </ProtectedRoute>
        }
      />
      <Route
        path="/new-booking"
        element={
          <ProtectedRoute allowedRole="client">
            <ClientDashboard view="new-booking" />
          </ProtectedRoute>
        }
      />
      <Route
        path="/my-bookings"
        element={
          <ProtectedRoute allowedRole="client">
            <ClientDashboard view="my-bookings" />
          </ProtectedRoute>
        }
      />
      <Route path="/login" element={<Login />} />
      <Route path="/register" element={<Register />} />
      <Route path="/client" element={<DefaultRoute />} />
      <Route
        path="/admin"
        element={
          <ProtectedRoute allowedRole="admin">
            <AdminDashboard />
          </ProtectedRoute>
        }
      />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

export default App;
